private Basket basket;

@BeforeEach
void setUp() {
    basket = new Basket();
}

@Test
void newBasketIsEmpty() {
    assertEquals(0, basket.totalInCents());
}

@Test
void oneItemCostsItsPrice() {
    basket.add(TEA);
    assertEquals(250, basket.totalInCents());
}

@Test
void quantityMultipliesThePrice() {
    basket.add(TEA, 3);
    assertEquals(750, basket.totalInCents());
}

@Test
void differentItemsAddUp() {
    basket.add(TEA, 2);
    basket.add(CAKE);
    assertEquals(900, basket.totalInCents());
}

@Test
void addingTheSameItemAgainAddsToItsQuantity() {
    basket.add(TEA);
    basket.add(TEA, 2);
    assertEquals(3, basket.quantityOf("TEA"));
    assertEquals(750, basket.totalInCents());
}

@Test
void removingAnItemTakesItOut() {
    basket.add(TEA, 2);
    basket.add(CAKE);
    basket.remove("TEA");
    assertEquals(0, basket.quantityOf("TEA"));
    assertEquals(400, basket.totalInCents());
}

@Test
void removingAnItemThatIsNotThereIsAnError() {
    assertThrows(IllegalArgumentException.class, () -> basket.remove("TEA"));
}

