package org.example.basket;

/** Something the shop sells. Prices are whole cents: 250 means 2.50. */
public record Item(String sku, String name, int priceInCents) {
    public Item {
        if (sku == null || sku.isBlank()) {
            throw new IllegalArgumentException("an item needs a SKU");
        }
        if (priceInCents < 0) {
            throw new IllegalArgumentException("a price can't be negative");
        }
    }
}

